with tempfile.TemporaryDirectory(prefix="ALS_important_plots_") as d:
    p=Path(d)
    for n,s in assets.items():
        if Path(n).name!=n:raise ValueError("Invalid helper name")
        (p/n).write_text(s)
    sys.exit(subprocess.run([sys.executable,"-u",str(p/"plot_important_snps.py"),*sys.argv[1:]]).returncode)
